    @Test void samePredecessorCompetingRequestsSerializeToOneRenewalAndOneSuperseded() throws Exception {
        var f=new Fixture();f.start();f.f.clock.value+=1000;byte[] one=f.renewal(UUID.randomUUID().toString()),two=f.renewal(UUID.randomUUID().toString());var start=new java.util.concurrent.CountDownLatch(1);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var a=pool.submit(()->{start.await();var r=f.service.renewExecution(f.f.identity,f.socket,one);AgentRuntimeV2ExecutionServiceImpl.outside();return r;});var b=pool.submit(()->{start.await();var r=f.service.renewExecution(f.f.identity,f.socket,two);AgentRuntimeV2ExecutionServiceImpl.outside();return r;});start.countDown();var results=List.of(a.get(20,java.util.concurrent.TimeUnit.SECONDS),b.get(20,java.util.concurrent.TimeUnit.SECONDS));assertEquals(1,results.stream().filter(r->f.reason(r).contains("grant.delivery")).count());assertEquals(1,results.stream().filter(r->f.reason(r).contains("RENEWAL_SUPERSEDED")).count());}assertEquals(2,f.f.count(FACT));assertEquals(2,f.f.count(GRANT));assertEquals(1,f.f.count(REQUEST));f.verifyPrior();
    }
    @Test void frozenLockTraceIncludesSourceAfterSortedDeploymentsAndBeforeBindingThenSuffix() throws Exception {
        for(String scope:List.of("TENANT_DRAIN","MODULE_QUIESCE","COMBINED")){var f=new Fixture();f.start();f.f.drain(f.registration,scope,"DRAINING");f.reconnect();var db=spy(f.f.db);var trace=new ArrayList<String>();doAnswer(call->{trace.add(call.getArgument(0)+" "+call.getArgument(1));return call.callRealMethod();}).when(db).lock(anyString(),anyMap());var authority=new AgentRuntimeV2ExecutionAuthority(db,f.f.keys,f.f.clock);var service=new AgentRuntimeV2ExecutionServiceImpl(f.store,authority,f.evidence,f.manager,f.f.clock);f.f.jdbc.locks.clear();assertFalse(service.continueExecution(f.f.identity,f.socket,f.continuation(UUID.randomUUID().toString())).close());var clients=trace.stream().filter(s->s.startsWith("oauth_client ")).toList();assertEquals(List.of("oauth_client {client_id=caller-client}","oauth_client {client_id=runtime-client}"),clients);var deployments=trace.stream().filter(s->s.startsWith("core_deployment_registration ")).toList();assertEquals(List.of("core_deployment_registration {deployment_id=local-api-a}","core_deployment_registration {deployment_id=producer-a}"),deployments);
            var locks=f.f.jdbc.locks;assertTrue(index(locks,"user_info")<index(locks,"oauth_api_key"));assertTrue(index(locks,"core_deployment_module_admission")<index(locks,"core_runtime_v2_drain_operation"));assertTrue(index(locks,"core_runtime_v2_drain_completion_authority")<index(locks,"agent_runtime_v2_binding"));if(!scope.equals("MODULE_QUIESCE"))assertTrue(index(locks,"core_deployment_module_admission")<index(locks,"core_tenant_operation")&&index(locks,"core_tenant_operation")<index(locks,"core_runtime_v2_drain_operation"));assertTrue(index(locks,"agent_consumer_inbox")<index(locks,RECEIPT));assertTrue(index(locks,RECEIPT)<index(locks,FACT)&&index(locks,FACT)<index(locks,ANCHOR)&&index(locks,ANCHOR)<index(locks,REQUEST)&&index(locks,REQUEST)<index(locks,GRANT));}
    }
