    @Test void renewalAfterEncodingAndFinalBeforeCommitOldExpiryEqualityBothRollBack() throws Exception {
        for(boolean precommit:List.of(false,true)){var f=new Fixture();f.start();f.f.clock.value+=1000;byte[] raw=f.renewal(UUID.randomUUID().toString());long boundary=number(f.latest(),"lease_until");var before=f.f.snapshot();var observed=new AtomicInteger();if(precommit){f.f.jdbc.afterWritePrefix="INSERT INTO "+REQUEST;f.f.jdbc.afterWrite=()->TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public int getOrder(){return Integer.MAX_VALUE-1;}public void beforeCommit(boolean readOnly){observed.incrementAndGet();f.f.clock.value=boundary;}});assertTrue(f.reason(f.service.renewExecution(f.f.identity,f.socket,raw)).contains("NOT_AUTHORIZED"));}else try(var codec=mockStatic(AgentRuntimeV2ExecutionCodec.class,CALLS_REAL_METHODS)){codec.when(()->AgentRuntimeV2ExecutionCodec.grantDelivery(any(),eq("RENEWAL"),anyString(),anyBoolean())).thenAnswer(call->{var result=call.callRealMethod();observed.incrementAndGet();f.f.clock.value=boundary;return result;});assertTrue(f.reason(f.service.renewExecution(f.f.identity,f.socket,raw)).contains("NOT_AUTHORIZED"));}assertEquals(1,observed.get());assertEquals(before,f.f.snapshot());AgentRuntimeV2ExecutionServiceImpl.outside();}
    }
    @Test void routingLeaseIsLivenessNotExecutionCapButItsFinalEqualityRollsBack() throws Exception {
        var f=new Fixture();f.start();long route=number(f.f.jdbc.queryForMap("SELECT * FROM agent_runtime_v2_binding"),"socket_owner_lease_until");assertTrue(number(f.latest(),"lease_until")>route);f.f.clock.value+=1000;byte[] raw=f.renewal(UUID.randomUUID().toString());var before=f.f.snapshot();f.f.jdbc.afterWritePrefix="INSERT INTO "+REQUEST;f.f.jdbc.afterWrite=()->f.f.clock.value=route;assertTrue(f.reason(f.service.renewExecution(f.f.identity,f.socket,raw)).contains("NOT_AUTHORIZED"));assertEquals(before,f.f.snapshot());
    }
    @Test void noAdvanceAndCredentialClippingDoNotManufactureExtension() throws Exception {
        var f=new Fixture();f.start();var before=f.f.snapshot();assertTrue(f.reason(f.service.renewExecution(f.f.identity,f.socket,f.renewal(UUID.randomUUID().toString()))).contains("NOT_AUTHORIZED"));assertEquals(before,f.f.snapshot());long until=number(f.latest(),"lease_until");f.f.jdbc.update("UPDATE oauth_api_key SET expire_time=?",until+1000);f.f.clock.value+=2000;f.renewRoute();assertFalse(f.service.renewExecution(f.f.identity,f.socket,f.renewal(UUID.randomUUID().toString())).close());assertEquals(until+1000,number(f.latest(),"lease_until"));
    }
    static int index(List<String> trace,String table){for(int n=0;n<trace.size();n++)if(trace.get(n).contains("FROM "+table+" WHERE"))return n;throw new AssertionError(table+trace);}
